"""Архитектура: высотные здания выше 75 м (жилые, общественные; СП 267, СП 477, СП 550) и жилые здания до 75 м (СП 54).
Группы EU: 'HR' (7.4), 'HP' (7.5), 'RS' (7.6)."""
import copy
from qlib import Q
from eudata import e,EU
from firedata import U,a
from hrdata import HT
U54='https://tiflocentre.ru/documents/sp_54.13330.2022.php'
S267=a('sp267','СП 267.1325800.2016 (ред. 30.12.2020)')
S477=a('sp477','СП 477.1325800.2020 (ред. 02.08.2024)')
S54=f'[СП 54.13330.2022 (с изм. 1, 2; копия tiflocentre.ru)]({U54})'
NA='⏳ не сверено'
HR=[]; HP=[]; RS=[]
KEYS=['ru','rs','eu','uk','ae']
def q267(l,q,ru): return ('q','СП 267.1325800.2016, '+l,q,ru)
def q54(l,q,ru): return ('q','СП 54.13330.2022, '+l,q,ru)
def topic(L,grp,slug,title,intro,ru,srcs,items,need,de=NA,fr=NA,at=NA,es=NA):
    """Россия — по документу; остальные страны — ⏳ с перечнем документов, которые нужно найти."""
    L.append(dict(slug=slug,title=title,intro=intro,keys=KEYS,
      cells={'ru':(ru,srcs),'rs':(NA+': '+need,[]),'eu':(de,[]),'uk':(NA+': '+need,[]),'ae':(NA+': '+need,[])},
      tabs={'ru':items,'rs':[('n','⏳ Нужно найти: '+need)],'eu':[],'uk':[('n','⏳ Нужно найти: '+need)],'ae':[('n','⏳ Нужно найти: '+need)]}))
    e(grp,slug,FR=(fr,[]),AT=(at,[]),ES=(es,[]))
def from_ht(L,grp,slug,title=None):
    t=copy.deepcopy(next(x for x in HT if x['slug']==slug))
    if title: t['title']=title
    t['keys']=KEYS; L.append(t); e(grp,slug,**EU[('H',slug)])
NEED_HR='Правила для высотных зданий (по странам): Сербия — правилник о высоких объектах и о планировании жилья; Англия — Approved Documents (B, K, Part M) для зданий выше 18 м; ЕС — муниципальные/земельные нормы; ОАЭ — Dubai Building Code (раздел о high-rise) и UAE Fire and Life Safety Code'
NOTE550='СП 477 заменяется СП 550.1311500.2026 — его текст ещё не получен (см. «Чего не хватает»)'

